  background-color: rgba(30, 30, 40, 0.95);
  color: white;
  font-family: 'Arial', sans-serif;
  padding: 20px;
  border-radius: 12px;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
}

.breathing-indicator {
  width: 12px;
  height: 12px;
  background-color: #FF69B4;
  border-radius: 50%;
  position: absolute;
  right: 15px;
  top: 15px;
  animation: breathe-and-spread 2s infinite ease-in-out;
}

.collapsible-header {
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 5px 0;
  border-bottom: 2px solid #FF69B4;
  margin-bottom: 15px;
}

.user-name {
  font-size: 18px;
  font-weight: bold;
  color: #FFB6C1;
}

.collapse-indicator {
  font-size: 14px;
  color: #DDA0DD;
  transition: transform 0.3s ease;
}

.user-content {
  transition: max-height 0.3s ease-out, opacity 0.3s ease-out;
  overflow: hidden;
}

.user-content.collapsed {
  max-height: 0;
  opacity: 0;
  margin: 0;
  padding: 0;
}

.user-content.expanded {
  max-height: 1000px;
  opacity: 1;
}

.user-status-section {
  margin-bottom: 12px;
  position: relative;
}

.user-status-label {
  font-weight: bold;
  color: #DDA0DD;
  display: inline-block;
  min-width: 80px;
}

.user-status-content {
  color: #F0F8FF;
  word-wrap: break-word;
}

.clothing-section {
  background: rgba(221, 160, 221, 0.1);
  padding: 10px;
  border-radius: 8px;
  margin: 10px 0;
}

.clothing-title {
  color: #DDA0DD;
  font-weight: bold;
  margin-bottom: 8px;
  text-align: center;
}

.progress-section {
  margin-top: 15px;
  padding: 10px;
  background: rgba(0, 0, 0, 0.3);
  border-radius: 8px;
}

.progress-item {
  margin-bottom: 12px;
}

.progress-label {
  display: flex;
  justify-content: space-between;
  margin-bottom: 5px;
  font-size: 12px;
}

.progress-bar {
  width: 100%;
  height: 12px;
  background-color: rgba(255, 255, 255, 0.2);
  border-radius: 6px;
  overflow: hidden;
  position: relative;
}

.progress-fill {
  height: 100%;
  border-radius: 6px;
  transition: width 0.8s ease-in-out;
  position: relative;
}

.corruption-fill {
  background: linear-gradient(90deg, #8A2BE2, #9932CC);
  animation: pulse-purple 2s infinite;
}

.pleasure-fill {
  background: linear-gradient(90deg, #FF69B4, #FF1493);
  animation: pulse-pink 2s infinite;
}

.progress-text {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 10px;
  font-weight: bold;
  color: white;
  text-shadow: 1px 1px 2px rgba(0,0,0,0.8);
}

@media screen and (max-width: 600px) {
  .user-status-panel-container {
    width: 95%;
  }

  .user-status-panel {
    font-size: 13px;
    padding: 15px;
  }

  .user-name {
    font-size: 16px;
  }
}
</style>
</head>
<body>
<div class="user-status-panel-container">
  <div class="user-status-panel">
    <div class="breathing-indicator"></div>

    <div class="collapsible-header" onclick="toggleCollapse()">
      <span class="user-name">👤 $1</span>
      <span class="collapse-indicator" id="indicator">▼</span>
    </div>

    <div class="user-content expanded" id="content">
      <div class="user-status-section">
        <span class="user-status-label">身份:</span>
        <span class="user-status-content">$2</span>
      </div>

      <div class="user-status-section">
        <span class="user-status-label">当前动作:</span>
        <span class="user-status-content">$3</span>
      </div>

      <div class="clothing-section">
        <div class="clothing-title">👗 服装状态</div>
        <div class="user-status-section">
          <span class="user-status-label">头部:</span>
          <span class="user-status-content">$4</span>
        </div>
        <div class="user-status-section">
          <span class="user-status-label">上身:</span>
          <span class="user-status-content">$5</span>
        </div>
        <div class="user-status-section">
          <span class="user-status-label">下身:</span>
          <span class="user-status-content">$6</span>
        </div>
        <div class="user-status-section">
          <span class="user-status-label">足部:</span>
          <span class="user-status-content">$7</span>
        </div>
        <div class="user-status-section">
          <span class="user-status-label">鞋子:</span>
          <span class="user-status-content">$8</span>
        </div>
      </div>

      <div class="user-status-section">
        <span class="user-status-label">💭 想法:</span>
        <span class="user-status-content">$9</span>
      </div>

      <div class="progress-section">
        <div class="progress-item">
          <div class="progress-label">
            <span style="color: #9932CC;">🧠 认知污染</span>
            <span id="corruption-value">$10</span>
          </div>
          <div class="progress-bar">
            <div class="progress-fill corruption-fill" id="corruption-bar">
              <div class="progress-text" id="corruption-text">$10</div>
            </div>
          </div>
        </div>

        <div class="progress-item">
          <div class="progress-label">
            <span style="color: #FF69B4;">💗 快感</span>
            <span id="pleasure-value">$11</span>
          </div>
          <div class="progress-bar">
            <div class="progress-fill pleasure-fill" id="pleasure-bar">
              <div class="progress-text" id="pleasure-text">$11</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>

<script>
function toggleCollapse() {
  const content = document.getElementById('content');
  const indicator = document.getElementById('indicator');

  if (content.classList.contains('expanded')) {
    content.classList.remove('expanded');
    content.classList.add('collapsed');
    indicator.textContent = '▶';
    indicator.style.transform = 'rotate(-90deg)';
  } else {
    content.classList.remove('collapsed');
    content.classList.add('expanded');
    indicator.textContent = '▼';
    indicator.style.transform = 'rotate(0deg)';
  }
}

// 解析并更新进度条
function updateProgressBars() {
  // 认知污染进度条
  const corruptionText = document.getElementById('corruption-value').textContent;
  const corruptionMatch = corruptionText.match(/(\d+)\/(\d+)/);
  if (corruptionMatch) {
    const current = parseInt(corruptionMatch[1]);
    const max = parseInt(corruptionMatch[2]);
    const percentage = (current / max) * 100;
    document.getElementById('corruption-bar').style.width = percentage + '%';
  }

  // 快感进度条
  const pleasureText = document.getElementById('pleasure-value').textContent;
  const pleasureMatch = pleasureText.match(/(\d+)\/(\d+)/);
  if (pleasureMatch) {
    const current = parseInt(pleasureMatch[1]);
    const max = parseInt(pleasureMatch[2]);
    const percentage = (current / max) * 100;
    document.getElementById('pleasure-bar').style.width = percentage + '%';
  }
}

// 页面加载时更新进度条
window.onload = function() {
  updateProgressBars();
};
</script>
</body>
</html>
